/** Poll the export's modified-time; rebuild the directory only when it's newer
 *  than the last sync. Cheap when unchanged (one Drive stat), so it can run
 *  often. Trigger target — installed by installFactsPoll_. */
var PROP_FACTS_MTIME = 'FACTS_LAST_MTIME';   // legacy per-project marker (migrated below)
var CFG_FACTS_MTIME = 'FactsLastSyncedMtime'; // shared marker in _System!Config

/**
 * The last-synced export mtime, kept in the SHARED _System Config (not per-project Script
 * Properties). Several apps (root project + apps/builder + …) each run this 4h poll against
 * the SAME _System, so a per-project marker made every one of them re-sync the same file.
 * With a shared marker the first app to see a new export does the work and the rest skip.
 * Migrates the old per-project value on first run so we don't re-sync unnecessarily.
 */
function factsLastSyncedMtime_() {
  var shared = Number(cfGetConfig_(CFG_FACTS_MTIME, '0') || 0);
  if (shared) return shared;
  var legacy = Number(PropertiesService.getScriptProperties().getProperty(PROP_FACTS_MTIME) || 0);
  if (legacy) { cfSetConfig_(CFG_FACTS_MTIME, String(legacy)); return legacy; }
  return 0;
}

function factsPollIfNewer_() {
  var file = factsResolveExportFile_();
  var mtime = file.getLastUpdated().getTime();
  if (mtime <= factsLastSyncedMtime_()) return { skipped: true, mtime: mtime };
  // Serialize across apps: two projects' triggers can fire at the same moment, and the
  // sync clears+rewrites shared tabs. Re-check inside the lock so only one does the work.
  return withLock_(function () {
    if (mtime <= factsLastSyncedMtime_()) return { skipped: true, mtime: mtime };
    var res = syncFactsDirectory_();
    cfSetConfig_(CFG_FACTS_MTIME, String(mtime));
    PropertiesService.getScriptProperties().setProperty(PROP_FACTS_MTIME, String(mtime)); // keep legacy in step
    Logger.log('FACTS poll: export newer → synced (' + JSON.stringify(res) + ').');
    return { synced: true, mtime: mtime, result: res };
  });
}

/** Install the poll trigger (every 4h). Seeds the last-seen mtime to the current
 *  export so it won't immediately re-sync what we already have. Run once. */
function installFactsPoll_() {
  ScriptApp.getProjectTriggers().forEach(function (t) {
    var h = t.getHandlerFunction();
    // remove the poll AND any legacy weekly/renamed sync triggers
    if (h === 'factsPollIfNewer_' || h === 'syncFactsDirectory_' || h === 'syncFactsDirectory') ScriptApp.deleteTrigger(t);
  });
  ScriptApp.newTrigger('factsPollIfNewer_').timeBased().everyHours(4).create();
  try {
    var file = factsResolveExportFile_();
    var mt = String(file.getLastUpdated().getTime());
    cfSetConfig_(CFG_FACTS_MTIME, mt);   // shared marker — see factsLastSyncedMtime_
    PropertiesService.getScriptProperties().setProperty(PROP_FACTS_MTIME, mt);
  } catch (e) { Logger.log('installFactsPoll_: could not seed mtime — ' + e.message); }
  Logger.log('FACTS poll installed (every 4h).');
}

/**
 * Remove this project's FACTS poll/sync triggers. Use on the app that should NOT own the
 * sync (only one needs the trigger; the shared marker makes extras harmless but wasteful).
 * @returns the number of triggers removed.
 */
function removeFactsPoll_() {
  var n = 0;
  ScriptApp.getProjectTriggers().forEach(function (t) {
    var h = t.getHandlerFunction();
    if (h === 'factsPollIfNewer_' || h === 'syncFactsDirectory_' || h === 'syncFactsDirectory') {
      ScriptApp.deleteTrigger(t); n++;
    }
  });
  Logger.log('Removed ' + n + ' FACTS trigger(s) from this project.');
  return { removed: n };
}

