function appsCacheKey_() { return contextCacheKey_('apps:all'); }

/** Full apps-registry read, cached 90s (CacheService) — was a full uncached
 *  getDataRange().getValues() on every portal load (via getPortalView). Invalidated on
 *  write by every admin mutator below. */
