    url: v[APP_COL.Url], iconEmoji: v[APP_COL.IconEmoji] || '', ownerEmail: v[APP_COL.OwnerEmail] || '',
    active: v[APP_COL.Active] !== false, lastCheckedAt: v[APP_COL.LastCheckedAt] || '',
    lastStatus: v[APP_COL.LastStatus] || 'unknown', lastStatusMsg: v[APP_COL.LastStatusMsg] || '',
