  if (data.Description != null) sh.getRange(r.rowIndex, APP_COL.Description + 1).setValue(String(data.Description).trim());
  if (data.Url != null) sh.getRange(r.rowIndex, APP_COL.Url + 1).setValue(String(data.Url).trim());
  if (data.IconEmoji != null) sh.getRange(r.rowIndex, APP_COL.IconEmoji + 1).setValue(String(data.IconEmoji).trim());
  if (data.OwnerEmail != null) sh.getRange(r.rowIndex, APP_COL.OwnerEmail + 1).setValue(String(data.OwnerEmail).trim());
  if (data.Active != null) sh.getRange(r.rowIndex, APP_COL.Active + 1).setValue(data.Active !== false);
  if (data.Slug != null) sh.getRange(r.rowIndex, APP_COL.Slug + 1).setValue(String(data.Slug).trim());
  if (data.SupportsHandoff != null) sh.getRange(r.rowIndex, APP_COL.SupportsHandoff + 1).setValue(data.SupportsHandoff === true);
  if (data.VisibleToParent != null) sh.getRange(r.rowIndex, APP_COL.VisibleToParent + 1).setValue(data.VisibleToParent === true);
  if (data.VisibleToStaff != null) sh.getRange(r.rowIndex, APP_COL.VisibleToStaff + 1).setValue(data.VisibleToStaff === true);
  if (data.VisibleToStudent != null) sh.getRange(r.rowIndex, APP_COL.VisibleToStudent + 1).setValue(data.VisibleToStudent === true);
  if (data.VisibleToGuest != null) sh.getRange(r.rowIndex, APP_COL.VisibleToGuest + 1).setValue(data.VisibleToGuest === true);
  if (data.LogoUrl != null) sh.getRange(r.rowIndex, APP_COL.LogoUrl + 1).setValue(String(data.LogoUrl).trim());
  if (data.Notes != null) sh.getRange(r.rowIndex, APP_COL.Notes + 1).setValue(String(data.Notes).trim());
