/** Remove an app registry entry by AppId. Admin-only. */
function adminDeleteApp(contextId, appId) {
  setActiveContext_(getContext_(contextId));
  requireAdmin_();
  var r = findAppRow_(appId);
  if (!r) throw new Error('App not found.');
  var logoFileId = logoFileIdFromUrl_(r.values[APP_COL.LogoUrl]);
  sysTab_(SYS.TABS.APPS).deleteRow(r.rowIndex);
  invalidateAppsCache_();
  if (logoFileId) {
    try { DriveApp.getFileById(logoFileId).setTrashed(true); } catch (e) { /* already gone — nothing to clean up */ }
  }
  return { ok: true };
}

/** A LogoUrl produced by adminUploadAppLogo() is 'https://drive.google.com/thumbnail?id=<fileId>&...'
 *  — pure extraction of that fileId, or null if LogoUrl isn't in that shape (e.g. blank, or an
 *  external image URL someone pasted in by hand — nothing to move for those). */
function logoFileIdFromUrl_(logoUrl) {
  var m = /[?&]id=([^&]+)/.exec(String(logoUrl || ''));
  return m ? m[1] : null;
}

/**
 * Move an app's registry row — and its uploaded logo file, if any — from the CURRENT context
 * (contextId) to another (toContextId). Admin-only: crosses a data boundary between two fully
 * separate _System spreadsheets. Keeps the same AppId (safe — different spreadsheet, no
 * collision risk).
 */
function adminMoveApp(contextId, appId, toContextId) {
  setActiveContext_(getContext_(contextId));
  requireAdmin_();
  var toCtx = getContext_(toContextId);
  if (!toCtx) throw new Error('Destination context not found: ' + toContextId);
  if (String(toContextId) === String(contextId)) throw new Error('Source and destination context are the same.');

  var r = findAppRow_(appId);
  if (!r) throw new Error('App not found.');
  var rowValues = r.values.slice();

  var logoFileId = logoFileIdFromUrl_(rowValues[APP_COL.LogoUrl]);
  if (logoFileId) {
    try {
      var file = DriveApp.getFileById(logoFileId);
      var destLogos = getOrCreateChild_(DriveApp.getFolderById(toCtx.rootFolderId), 'App Logos');
      destLogos.addFile(file);
      var oldParents = file.getParents();
      while (oldParents.hasNext()) {
        var op = oldParents.next();
        if (op.getId() !== destLogos.getId()) op.removeFile(file);
      }
    } catch (e) { /* logo file missing/inaccessible — app row still moves, just without it */ }
  }

  setActiveContext_(toCtx);
  sysTab_(SYS.TABS.APPS).appendRow(rowValues);
  invalidateAppsCache_();

  setActiveContext_(getContext_(contextId));
  var r2 = findAppRow_(appId);
  if (r2) sysTab_(SYS.TABS.APPS).deleteRow(r2.rowIndex);
  invalidateAppsCache_();

  return { ok: true, appId: appId, movedTo: toContextId };
}

/** Ping one app's URL, record its status against whatever context is currently active. Never
 *  throws on network failure — records 'down' with the error message instead. Caller must have
 *  already set the active context and checked permissions (see adminCheckAppStatus for the
 *  admin-gated entry point, checkAllAppsStatusAcrossContexts_ for the trigger-driven one). */
function checkAppStatus_(appId) {
  var r = findAppRow_(appId);
  if (!r) throw new Error('App not found.');
  var url = r.values[APP_COL.Url];
  var status = 'down', msg = '';
  try {
    var resp = UrlFetchApp.fetch(url, { muteHttpExceptions: true, followRedirects: true });
    var code = resp.getResponseCode();
    status = classifyHttpStatus_(code);
    msg = String(code);
  } catch (e) {
    msg = String(e && e.message || e);
  }
  var sh = sysTab_(SYS.TABS.APPS);
  sh.getRange(r.rowIndex, APP_COL.LastCheckedAt + 1).setValue(new Date().toISOString());
  sh.getRange(r.rowIndex, APP_COL.LastStatus + 1).setValue(status);
  sh.getRange(r.rowIndex, APP_COL.LastStatusMsg + 1).setValue(msg);
  invalidateAppsCache_();
  return appRowToObj_(findAppRow_(appId).values);
}

/** Ping one app's URL, record + return its updated status. Admin-only. */
function adminCheckAppStatus(contextId, appId) {
  setActiveContext_(getContext_(contextId));
  requireAdmin_();
  return checkAppStatus_(appId);
}

/** Check every active app in one context. Admin-only. Returns all rows (active + inactive) post-check. */
function adminCheckAllAppsStatus(contextId) {
  setActiveContext_(getContext_(contextId));
  requireAdmin_();
  var rows = sysTab_(SYS.TABS.APPS).getDataRange().getValues().slice(1)
    .filter(function (r) { return r[APP_COL.AppId]; });
  rows.forEach(function (r) {
    if (r[APP_COL.Active] !== false) checkAppStatus_(r[APP_COL.AppId]);
  });
  return adminListApps(contextId);
}

/** Trigger-only (no admin gate — runs with no signed-in caller): pings every active app across
 *  EVERY registered context (falls back to the single default context if none are registered
 *  yet, e.g. before adminBootstrapContextsRegistry has run). Installed via
 *  adminInstallAppStatusTrigger (Maintenance.js) so a linked app going down gets reflected
 *  within hours instead of waiting for an admin to remember to click "Check status." */
function checkAllAppsStatusAcrossContexts_() {
  var contexts = listContexts_();
  var targets = contexts.length ? contexts.map(function (c) { return c.contextId; }) : [null];
  targets.forEach(function (contextId) {
    setActiveContext_(getContext_(contextId));
    var rows = sysTab_(SYS.TABS.APPS).getDataRange().getValues().slice(1)
      .filter(function (r) { return r[APP_COL.AppId]; });
    rows.forEach(function (r) {
      if (r[APP_COL.Active] === false) return;
      try { checkAppStatus_(r[APP_COL.AppId]); } catch (e) { /* one app's failure shouldn't skip the rest */ }
    });
  });
}

/** Install the every-6h app-status-check trigger. Run once (Maintenance.js's
 *  adminInstallAppStatusTrigger wraps this for the editor Run menu). */
function installAppStatusTrigger_() {
  ScriptApp.getProjectTriggers().forEach(function (t) {
    if (t.getHandlerFunction() === 'checkAllAppsStatusAcrossContexts_') ScriptApp.deleteTrigger(t);
  });
  ScriptApp.newTrigger('checkAllAppsStatusAcrossContexts_').timeBased().everyHours(6).create();
  return { ok: true };
}

