/**
 * Splits a multi-page PDF into single-page PDF blobs using vendored pdf-lib — needed because
 * Drive's thumbnailLink only ever renders page 1 of a multi-page PDF, and every page needs its
 * own pixel-accurate background.
 */
async function splitPdfIntoSinglePagePdfs_(pdfBlob) {
  var pdfBytes = new Uint8Array(pdfBlob.getBytes());
  var srcDoc = await PDFLib.PDFDocument.load(pdfBytes);
  var pageCount = srcDoc.getPageCount();

  var pageBlobs = [];
  for (var i = 0; i < pageCount; i++) {
    var newDoc = await PDFLib.PDFDocument.create();
    var copiedPages = await newDoc.copyPages(srcDoc, [i]);
    newDoc.addPage(copiedPages[0]);
    var bytes = await newDoc.save();
    pageBlobs.push(Utilities.newBlob(bytes, 'application/pdf', 'page' + i + '.pdf'));
  }
  return pageBlobs;
}

/** Real page dimensions (points) — used to scale mapper-drawn boxes against the seed
 *  presentation's actual page size, and to report widthPt/heightPt to the Builder mapper UI. */
async function getPdfPageSizes_(pdfBytes) {
  var doc = await PDFLib.PDFDocument.load(pdfBytes);
  var sizes = [];
  for (var i = 0; i < doc.getPageCount(); i++) {
    var size = doc.getPage(i).getSize();
    sizes.push({ width: size.width, height: size.height });
  }
  return sizes;
}

