var THUMBNAIL_POLL_MAX_ATTEMPTS = 15;
var THUMBNAIL_POLL_INITIAL_DELAY_MS = 1000;
var THUMBNAIL_POLL_MAX_DELAY_MS = 5000;

/** pdfPageBlob: a single-page PDF Blob. Returns a PNG Blob. Uploads a throwaway Drive file to
 *  get a thumbnail, then trashes it once the PNG bytes are fetched. Known limitation: Drive's
 *  thumbnailLink caps out around 1024px on a portrait Letter page even when a larger size is
 *  requested — fine print may render less sharp than the source PDF. */
function rasterizePdfPageToPng_(pdfPageBlob) {
  var file = DriveApp.createFile(pdfPageBlob);
  var fileId = file.getId();
  try {
    var thumbnailLink = pollForThumbnailLink_(fileId);
    var response = UrlFetchApp.fetch(requestLargestThumbnailSize_(thumbnailLink), {
      headers: { Authorization: 'Bearer ' + ScriptApp.getOAuthToken() }
    });
    return response.getBlob().setName('page.png');
  } finally {
    file.setTrashed(true);
  }
}

function requestLargestThumbnailSize_(thumbnailLink) {
  return /=s\d+$/.test(thumbnailLink)
    ? thumbnailLink.replace(/=s\d+$/, '=s1600')
    : thumbnailLink + '=s1600';
}

/** Thumbnail generation is an async Google-side job with no documented SLA — exponential
 *  backoff up to ~50s total budget rather than a flat short timeout. */
function pollForThumbnailLink_(fileId) {
  var delay = THUMBNAIL_POLL_INITIAL_DELAY_MS;
  for (var attempt = 1; attempt <= THUMBNAIL_POLL_MAX_ATTEMPTS; attempt++) {
    var meta = Drive.Files.get(fileId, { fields: 'thumbnailLink' });
    if (meta.thumbnailLink) return meta.thumbnailLink;
    Utilities.sleep(delay);
    delay = Math.min(delay * 1.5, THUMBNAIL_POLL_MAX_DELAY_MS);
  }
  throw new Error('Drive thumbnailLink never became available for file ' + fileId +
    ' after ' + THUMBNAIL_POLL_MAX_ATTEMPTS + ' attempts.');
}

