  var placedH = box.h * scaleY;

  var fontSize = fontSizeForBox_(placedW, placedH);
  var displayTag = truncateForDisplay_(box.tag, placedW, fontSize);

  var shape = slide.insertTextBox('{{' + displayTag + '}}', box.x * scaleX, box.y * scaleY, placedW, placedH);
  var textRange = shape.getText();
  textRange.getTextStyle().setFontFamily('Arial').setFontSize(fontSize).setForegroundColor('#000000');
  textRange.getParagraphStyle().setParagraphAlignment(SlidesApp.ParagraphAlignment.START);
  shape.getFill().setTransparent();
  shape.getBorder().setTransparent();
