// ---------- Approval groups (Approval_Groups tab: GroupName | MemberEmails | Notes) ----------

/** Pure. Validate + normalize one group. Returns {ok, group} or {ok:false, message}. */
function normalizeApprovalGroup_(data, allowed) {
  var name = String((data && data.name) || '').trim();
  if (!name) return { ok: false, message: 'Give the group a name.' };
  if (name.indexOf('@') > -1 || name.indexOf(',') > -1) return { ok: false, message: 'A group name can’t contain “@” or a comma — those are how a form tells a group apart from an email address.' };
  var raw = Array.isArray(data.members) ? data.members : String(data.members || '').split(/[,;\s]+/);
  var members = [], bad = [];
  raw.forEach(function (e) {
    var norm = String(e || '').trim().toLowerCase();
    if (!norm) return;
    if (!allowed(norm)) { bad.push(norm); return; }
    if (members.indexOf(norm) < 0) members.push(norm);
  });
  if (bad.length) return { ok: false, message: 'These aren’t school email addresses, so they can’t approve: ' + bad.join(', ') };
  if (!members.length) return { ok: false, message: 'Add at least one member email.' };
  return { ok: true, group: { name: name, members: members, notes: String((data && data.notes) || '').trim() } };
}

function approvalGroupsTab_() { return sysGetOrCreateTab_(getSystemSpreadsheet_(), SYS.TABS.GROUPS, SYS_HEADERS.Approval_Groups); }

function listApprovalGroups_() {
  return approvalGroupsTab_().getDataRange().getValues().slice(1).filter(function (r) { return String(r[0] || '').trim(); }).map(function (r) {
    return { name: String(r[0]).trim(), members: String(r[1] || '').split(',').map(function (e) { return e.trim(); }).filter(Boolean), notes: String(r[2] || '').trim() };
  });
}

/** Every group in this context. Admin-only. */
function adminListApprovalGroups(contextId) {
  setActiveContext_(getContext_(contextId));
  requireAdmin_();
  return listApprovalGroups_();
}

/** Create (originalName blank) or update (rename allowed) a group. Admin-only. Returns the list. */
function adminSaveApprovalGroup(contextId, originalName, data) {
  setActiveContext_(getContext_(contextId));
  requireAdmin_();
  var v = normalizeApprovalGroup_(data, notifyAddrAllowed_);
  if (!v.ok) throw new Error(v.message);
  var g = v.group, orig = String(originalName || '').trim().toLowerCase();
  return withLock_(function () {
    var sh = approvalGroupsTab_(), vals = sh.getDataRange().getValues(), at = -1;
    // No renames: forms reference a group by its NAME (a text token in their Approvers box),
    // so renaming would silently leave those forms routing to nobody — and a form whose only
    // approver was that group would then skip approval entirely (resolveApproval_).
    if (orig && orig !== g.name.toLowerCase()) throw new Error('A group can’t be renamed — forms find it by name. Create a new group instead, switch the forms over, then delete the old one.');
    for (var i = 1; i < vals.length; i++) {
      var n = String(vals[i][0] || '').trim().toLowerCase();
      if (orig && n === orig) at = i;
      else if (n && n === g.name.toLowerCase()) throw new Error('There’s already a group called “' + g.name + '”.');
    }
    var row = [g.name, g.members.join(', '), g.notes];
    if (at > -1) sh.getRange(at + 1, 1, 1, 3).setValues([row]); else sh.appendRow(row);
    return listApprovalGroups_();
  });
}

/** Delete a group by name. Admin-only. Returns the list. */
function adminDeleteApprovalGroup(contextId, name) {
  setActiveContext_(getContext_(contextId));
  requireAdmin_();
  var norm = String(name || '').trim().toLowerCase();
  return withLock_(function () {
    var sh = approvalGroupsTab_(), vals = sh.getDataRange().getValues();
    for (var i = 1; i < vals.length; i++) if (String(vals[i][0] || '').trim().toLowerCase() === norm) { sh.deleteRow(i + 1); break; }
    return listApprovalGroups_();
  });
}

// ---------- Staff directory (Staff tab: Name | Email | Dept | Level | Active) ----------

var STAFF_LEVELS_ = { '': 1, HS: 1, MS: 1, EL: 1 };

/** Pure. Validate + normalize one staff row. */
function normalizeStaffEntry_(data) {
  var name = String((data && data.name) || '').trim();
  if (!name) return { ok: false, message: 'Name is required.' };
  var email = String((data && data.email) || '').trim().toLowerCase();
  if (email && !EMAIL_RE.test(email)) return { ok: false, message: '“' + email + '” isn’t a valid email address.' };
  var level = String((data && data.level) || '').trim().toUpperCase();
  if (!STAFF_LEVELS_[level]) return { ok: false, message: 'Level must be HS, MS, EL, or blank (any).' };
  return { ok: true, entry: { name: name, email: email, dept: String((data && data.dept) || '').trim(), level: level, active: !(data && data.active === false) } };
}

function staffTab_() { return sysGetOrCreateTab_(getSystemSpreadsheet_(), SYS.TABS.STAFF, SYS_HEADERS.Staff); }

/** A row's identity: email when it has one, else name (lowercased). */
