    var active = !(r[4] === false || String(r[4]).toUpperCase() === 'FALSE');
    return { key: staffKey_(r[0], r[1]), name: String(r[0]).trim(), email: String(r[1] || '').trim(), dept: String(r[2] || '').trim(), level: String(r[3] || '').trim().toUpperCase(), active: active };
