/** Create (key blank) or update a staff row. Admin-only. Returns the list. */
function adminSaveStaff(contextId, key, data) {
  setActiveContext_(getContext_(contextId));
  requireAdmin_();
  var v = normalizeStaffEntry_(data);
  if (!v.ok) throw new Error(v.message);
  var s = v.entry, newKey = staffKey_(s.name, s.email), oldKey = String(key || '');
  return withLock_(function () {
    var sh = staffTab_(), vals = sh.getDataRange().getValues(), at = -1;
    for (var i = 1; i < vals.length; i++) {
      if (!String(vals[i][0] || '').trim()) continue;
      var k = staffKey_(vals[i][0], vals[i][1]);
      if (oldKey && k === oldKey) at = i;
      else if (k === newKey) throw new Error('That person is already in the staff directory.');
    }
    var row = [s.name, s.email, s.dept, s.level, s.active];
    if (at > -1) sh.getRange(at + 1, 1, 1, 5).setValues([row]); else sh.appendRow(row);
    return listStaff_();
  });
}

/** Delete a staff row by key. Admin-only. Returns the list. */
function adminDeleteStaff(contextId, key) {
  setActiveContext_(getContext_(contextId));
  requireAdmin_();
  return withLock_(function () {
    var sh = staffTab_(), vals = sh.getDataRange().getValues();
    for (var i = 1; i < vals.length; i++) { // first match only — never sweep up a same-named duplicate
      if (String(vals[i][0] || '').trim() && staffKey_(vals[i][0], vals[i][1]) === String(key || '')) { sh.deleteRow(i + 1); break; }
    }
    return listStaff_();
  });
}

// ---------- FACTS data (Config FactsExportFileId/FactsExportFileName + the sync) ----------

/** Pure. Accept a bare Drive id or any Drive/Docs URL and return the id ('' if none). */
function driveIdFromInput_(s) {
  var t = String(s || '').trim();
  if (!t) return '';
  var m = t.match(/\/d\/([A-Za-z0-9_-]{10,})/) || t.match(/\/folders\/([A-Za-z0-9_-]{10,})/) || t.match(/[?&]id=([A-Za-z0-9_-]{10,})/);
  if (m) return m[1];
  return /^[A-Za-z0-9_-]{10,}$/.test(t) ? t : '';
}

/** FACTS data is HCS's family directory — refuse to read/sync it into a context that has no
 *  FACTS (MACS's 'open-picker'), where a blank FactsExportFileId would otherwise search the
 *  deployer's whole Drive by name and import HCS student/guardian PII into the wrong _System. */
function requireFactsContext_(contextId) {
  var ctx = getContext_(contextId);
  if (ctx && ctx.authMode === 'open-picker') throw new Error('This context doesn’t use FACTS data.');
}

function factsTabRowCount_(name) {
  var sh = sysTab_(name);
  return sh ? Math.max(0, sh.getLastRow() - 1) : 0;
}

/** What the FACTS panel shows: source config, last sync, and what's loaded now. Admin-only. */
function adminFactsStatus(contextId) {
  setActiveContext_(getContext_(contextId));
  requireAdmin_();
  requireFactsContext_(contextId);
  var mtime = Number(cfGetConfig_('FactsLastSyncedMtime', '0') || 0);
  var out = {
    fileId: cfGetConfig_('FactsExportFileId', ''),
    fileName: cfGetConfig_('FactsExportFileName', 'FACTS_Export.xlsx'),
    lastSyncedExportAt: mtime ? new Date(mtime).toISOString() : '',
    counts: { directoryRows: factsTabRowCount_(SYS.TABS.DIRECTORY), classRows: factsTabRowCount_(SYS.TABS.CLASSES), staffRows: factsTabRowCount_(SYS.TABS.FACTS_STAFF) },
    resolved: null, resolveError: ''
  };
  try {
    var f = factsResolveExportFile_();
    out.resolved = { name: f.getName(), updatedAt: f.getLastUpdated().toISOString(), newerThanLastSync: f.getLastUpdated().getTime() > mtime };
  } catch (e) { out.resolveError = String(e && e.message || e); }
  return out;
}

/** Point the sync at a different export file or folder. Admin-only. */
function adminSetFactsSource(contextId, fileIdOrUrl, fileName) {
  setActiveContext_(getContext_(contextId));
  requireAdmin_();
  requireFactsContext_(contextId);
  var raw = String(fileIdOrUrl || '').trim();
  var id = driveIdFromInput_(raw);
  if (raw && !id) throw new Error('That doesn’t look like a Google Drive link or file id.');
  var name = String(fileName || '').trim() || 'FACTS_Export.xlsx';
  cfSetConfig_('FactsExportFileId', id);
  cfSetConfig_('FactsExportFileName', name);
  return adminFactsStatus(contextId);
}

/** Re-read the export now and rebuild the directory (same lock + marker as the 4h poll). Admin-only. */
function adminFactsSyncNow(contextId) {
  setActiveContext_(getContext_(contextId));
  requireAdmin_();
  requireFactsContext_(contextId);
  var file = factsResolveExportFile_();
  var mtime = file.getLastUpdated().getTime();
  var res = withLock_(function () {
    var r = syncFactsDirectory_();
    cfSetConfig_('FactsLastSyncedMtime', String(mtime)); // so the background poll doesn't redo it
    return r;
  });
  return { ok: true, result: res, status: adminFactsStatus(contextId) };
}

/** Read-only checks on the export (row counts, header sanity). Admin-only. */
function adminFactsValidate(contextId) {
  setActiveContext_(getContext_(contextId));
  requireAdmin_();
  requireFactsContext_(contextId);
  return adminValidateFactsExport();
}

/** Read-only: which Drive file the sync will pick, and why. Admin-only. */
function adminFactsDiagnose(contextId) {
  setActiveContext_(getContext_(contextId));
  requireAdmin_();
  requireFactsContext_(contextId);
  return adminDiagnoseFactsFile();
}

// ---------- Site settings (Config tab keys that used to need the spreadsheet or editor) ----------

/** Every Config key the Site settings page may write, with its validator. */
var SITE_SETTING_KEYS_ = ['SCHOOL_YEAR', 'SCHOOL_YEAR_ROLLOVER_MONTH', 'SUPPORT_CONTACT', 'NOTIFY_EXTRA_DOMAINS',
  'PARENT_SESSION_TTL_HOURS', 'PhysicalMirrorSheetId', 'PhysicalMirrorTab', 'DEV_EMAIL', 'OPS_EMAIL', 'ORG_NAME'];

/**
 * Pure. Validate + normalize one Site settings value. Blank always means "use the default".
 * `allowed` = the in-house address check (notifyAddrAllowed_). Returns {ok, value} or {ok:false, message}.
 */
function normalizeSiteSetting_(key, value, allowed) {
  var v = String(value == null ? '' : value).trim();
  if (SITE_SETTING_KEYS_.indexOf(key) === -1) return { ok: false, message: 'Unknown setting: ' + key };
  if (!v) return { ok: true, value: '' };
  switch (key) {
    case 'SCHOOL_YEAR': {
      var m = v.match(/^(\d{4})\s*[-–\/]\s*(\d{2}|\d{4})$/);
      if (!m) return { ok: false, message: 'School year should look like 2026-2027 (or leave it blank to work it out from the date).' };
      var start = Number(m[1]), end = m[2].length === 2 ? Number(m[1].slice(0, 2) + m[2]) : Number(m[2]);
      if (end !== start + 1) return { ok: false, message: 'School year must be two consecutive years, like 2026-2027.' };
      return { ok: true, value: start + '-' + end };
    }
    case 'SCHOOL_YEAR_ROLLOVER_MONTH': {
      var n = Number(v);
      if (!(n >= 1 && n <= 12 && Math.floor(n) === n)) return { ok: false, message: 'Rollover month must be 1–12.' };
      return { ok: true, value: String(n) };
    }
    case 'PARENT_SESSION_TTL_HOURS': {
      var h = Number(v);
      if (!(h >= 1 && h <= 2160 && Math.floor(h) === h)) return { ok: false, message: 'Parent sign-in length must be a whole number of hours from 1 to 2160 (90 days).' };
      return { ok: true, value: String(h) };
    }
    case 'NOTIFY_EXTRA_DOMAINS': {
      var doms = [], badD = [];
      v.split(/[,;\s]+/).forEach(function (d) {
        var x = d.trim().toLowerCase().replace(/^@/, '');
        if (!x) return;
        if (!/^[a-z0-9-]+(\.[a-z0-9-]+)+$/.test(x)) badD.push(d); else if (doms.indexOf(x) < 0) doms.push(x);
      });
      if (badD.length) return { ok: false, message: 'Not a valid domain: ' + badD.join(', ') + ' (use e.g. example.org).' };
      return { ok: true, value: doms.join(', ') };
    }
    case 'DEV_EMAIL': case 'OPS_EMAIL': {
      var ems = [], badE = [];
      v.split(/[,;\s]+/).forEach(function (e) {
        var x = e.trim().toLowerCase();
        if (!x) return;
        if (!allowed(x)) badE.push(x); else if (ems.indexOf(x) < 0) ems.push(x);
      });
      if (badE.length) return { ok: false, message: 'Only school email addresses can receive these (they can contain parent and student data): ' + badE.join(', ') };
      return { ok: true, value: ems.join(',') };
    }
    case 'PhysicalMirrorSheetId': {
      var id = driveIdFromInput_(v);
      if (!id) return { ok: false, message: 'That doesn’t look like a Google Sheets link or id.' };
      return { ok: true, value: id };
    }
    default: // SUPPORT_CONTACT, PhysicalMirrorTab, ORG_NAME — free text
      if (v.length > 200) return { ok: false, message: 'That’s too long (200 characters max).' };
      return { ok: true, value: v };
  }
}

function siteSettingsView_() {
  var vals = {};
  SITE_SETTING_KEYS_.forEach(function (k) { vals[k] = cfGetConfig_(k, ''); });
  var st = Mailer.devOverrideStatus();
  return { values: vals, testMode: { active: st.active, sendsTo: st.devEmail }, sessionEpoch: Number(cfGetConfig_('SESSION_EPOCH', '1')) || 1,
    derivedSchoolYear: RespSheetLogic.schoolYearFor(new Date(), Number(vals.SCHOOL_YEAR_ROLLOVER_MONTH || 7)) };
}

/** Site settings for this context. Admin-only. */
function adminGetSiteSettings(contextId) {
  setActiveContext_(getContext_(contextId));
  requireAdmin_();
  return siteSettingsView_();
}

/** Save any subset of Site settings ({KEY: value}). Validates ALL before writing ANY. Admin-only. */
function adminSaveSiteSettings(contextId, patch) {
  setActiveContext_(getContext_(contextId));
  requireAdmin_();
  var clean = {}, errs = [];
  Object.keys(patch || {}).forEach(function (k) {
    var r = normalizeSiteSetting_(k, patch[k], notifyAddrAllowed_);
    if (r.ok) clean[k] = r.value; else errs.push(r.message);
  });
  if (errs.length) throw new Error(errs.join(' '));
  Object.keys(clean).forEach(function (k) { cfSetConfig_(k, clean[k]); });
  return siteSettingsView_();
}

/** Break-glass: invalidate every parent sign-in AND every emailed edit/withdraw link. Admin-only. */
function adminSignOutAllParents(contextId) {
  setActiveContext_(getContext_(contextId));
  requireAdmin_();
  return withLock_(function () {
    var next = (Number(cfGetConfig_('SESSION_EPOCH', '1')) || 1) + 1;
    cfSetConfig_('SESSION_EPOCH', String(next));
    return siteSettingsView_();
  });
}

