/**
 * Maintenance.js — admin-only entry points you RUN FROM THE APPS SCRIPT EDITOR.
 *
 * Why this file exists: the real maintenance functions end in "_" so the public web deployment
 * can't invoke them (google.script.run refuses trailing-underscore names). But the editor's Run
 * menu ALSO hides "_" functions, so these plainly-named wrappers give you something to pick in the
 * Run dropdown. Each is guarded by assertAdminRun_(): in the editor you're the signed-in admin, so
 * it runs; an anonymous web caller resolves to no email and is rejected.
 *
 * To run one: open this file (Maintenance.gs) in the editor, choose the function in the Run
 * dropdown at the top, and click ▶ Run.
 */

/** Reject anyone who isn't a signed-in HCS Forms admin (editor = you; anonymous web = blocked). */
function assertAdminRun_() {
  var who = String(Session.getActiveUser().getEmail() || '');
  if (!isAdmin_(who)) {
    throw new Error('Admin-only maintenance action. Run this as an HCS Forms admin (you appear as: "' + who + '").');
  }
  return who;
}

