/**
 * READ-ONLY: report exactly which Drive file the FACTS sync will read, and why. Run this when
 * a sync/validate fails with a Drive or mime-type error — it resolves the same file the sync
 * would, prints its name/type/size, and if Config points at a FOLDER it lists every candidate
 * inside so a stray non-spreadsheet is obvious. Touches nothing.
 */
function adminDiagnoseFactsFile() {
  assertAdminRun_();
  var out = { config: {}, resolved: null, folderCandidates: null, verdict: '' };
  var wantName = cfGetConfig_('FactsExportFileName', 'FACTS_Export.xlsx');
  var fileId = cfGetConfig_('FactsExportFileId', '');
  out.config = { FactsExportFileId: fileId || '(blank)', FactsExportFileName: wantName };

  // Is the configured id a FILE, a FOLDER, or neither?
  // getFileById succeeds on a FOLDER id too, so classify by mime type, not by whether it threw.
  var asFile = null, asFolder = null;
  if (fileId) {
    try { asFile = DriveApp.getFileById(fileId); } catch (e) {}
    if (asFile && String(asFile.getMimeType()) === FACTS_FOLDER_MIME) {
      asFile = null;
      try { asFolder = DriveApp.getFolderById(fileId); } catch (e) {}
    } else if (!asFile) {
      try { asFolder = DriveApp.getFolderById(fileId); } catch (e) {}
    }
    out.config.idPointsAt = asFile ? 'FILE' : (asFolder ? 'FOLDER' : 'NEITHER (bad id / no access)');
  }

  var describe = function (f) {
    return { name: f.getName(), mimeType: String(f.getMimeType()),
             sizeKB: (function () { try { return Math.round(f.getSize() / 1024); } catch (e) { return null; } })(),
             lastUpdated: String(f.getLastUpdated()), id: f.getId(),
             usableAsWorkbook: factsIsSpreadsheetLike_(f) };
  };

  if (asFolder) {
    out.folderCandidates = [];
    var it = asFolder.getFiles();
    while (it.hasNext()) out.folderCandidates.push(describe(it.next()));
    out.folderCandidates.sort(function (a, b) { return a.lastUpdated < b.lastUpdated ? 1 : -1; });
  }

  try {
    var f = factsResolveExportFile_();
    out.resolved = describe(f);
    if (!out.resolved.usableAsWorkbook) {
      out.verdict = 'PROBLEM: resolved "' + out.resolved.name + '" (' + out.resolved.mimeType +
        '), which is NOT a spreadsheet. Point FactsExportFileId at the export FILE, or rename the upload to "' + wantName + '".';
    } else if (out.resolved.mimeType === 'application/vnd.google-apps.spreadsheet') {
      out.verdict = 'OK — native Google Sheet, read directly (no conversion needed).';
    } else {
      out.verdict = 'OK — will be converted to a temp Google Sheet for reading.';
    }
    // Which sheet tabs does the sync expect vs. what's actually in there?
    try {
      var sheets = factsReadExportSheets_(['Sheet1', 'Student Schedules', 'Teachers', 'Staff']);
      out.sheetRowCounts = {};
      Object.keys(sheets).forEach(function (n) { out.sheetRowCounts[n] = (sheets[n] || []).length; });
      var missing = Object.keys(out.sheetRowCounts).filter(function (n) { return !out.sheetRowCounts[n]; });
      if (missing.length) out.verdict += ' WARNING: expected sheet tab(s) empty/missing: ' + missing.join(', ') + '.';
    } catch (e2) { out.verdict += ' Could not read sheet tabs: ' + (e2 && e2.message || e2); }
  } catch (e) {
    out.verdict = 'RESOLVE FAILED: ' + (e && e.message || e);
  }

  Logger.log(JSON.stringify(out, null, 2));
  return out;
}

