function adminReseedForms() {
  assertAdminRun_();
  return seedAllForms_(); // iterates SEED_FNS_ (Seeds.js) — the single seed registry
}

/**
 * Register this app's OWN Script-Properties-configured _System/Drive root as the "hcs"
 * context in the Contexts registry (see gas-shared/ContextRegistry.js), so the Builder's
 * "Manage Contexts" tab shows it from day one. Idempotent — a no-op if 'hcs' is already
 * registered. Run once, in apps/builder only, after adding a second context (e.g. MACS).
 */
/**
 * Round-2 audit (P24) cleanup: signature PNGs used to be shared ANYONE_WITH_LINK when composited
 * into a PDF template's Slides deck, and never revoked — the code path is fixed (see
 * signatureImageRequests_/fillTemplateFields_ in PdfTemplate.js), but exposure that already
 * happened doesn't fix itself. Walks every form's Uploads/** in THIS context and re-privatizes
 * any file whose name matches /signature/i. Run once per context after deploying the fix
 * (idempotent — re-running finds nothing left to do once it's clean).
 */
function adminRevokeSignatureSharing() {
  assertAdminRun_();
  var out = { scannedForms: 0, revoked: [], errors: [] };
  allRegistryRows_().forEach(function (r) {
    var formId = r[REG_COL.FormID], folderId = r[REG_COL.FolderId];
    if (!folderId) return;
    out.scannedForms++;
    try {
      var uploadsIt = DriveApp.getFolderById(folderId).getFoldersByName('Uploads');
      if (!uploadsIt.hasNext()) return;
      var uploads = uploadsIt.next();
      var subIt = uploads.getFolders(); // one subfolder per submissionId
      while (subIt.hasNext()) {
        var sub = subIt.next();
        var filesIt = sub.getFiles();
        while (filesIt.hasNext()) {
          var f = filesIt.next();
          if (!/signature/i.test(f.getName())) continue;
          try {
            f.setSharing(DriveApp.Access.PRIVATE, DriveApp.Permission.NONE);
            out.revoked.push(formId + '/' + sub.getName() + '/' + f.getName());
          } catch (e) { out.errors.push(formId + '/' + f.getName() + ': ' + (e && e.message || e)); }
        }
      }
    } catch (e2) { out.errors.push(formId + ': ' + (e2 && e2.message || e2)); }
  });
  Logger.log(JSON.stringify(out, null, 2));
  return out;
}

