// Single source of truth for "all built-in forms" — iterate this, never a hand-copied list.
var SEED_FNS_ = [seedSampleForm_, seedParentForm_, seedConferenceForm_, seedPhysicalForm_,
  seedIodineForm_, seedFieldTripForm_, seedCourseSelectionForm_, seedHomeschoolForm_,
  seedTripRequestForm_, seedMedicationForm_, seedSupplyListForm_, seedAtHomeLearningForm_];

/** (Re)seed every built-in form. Returns the list of form ids (or ERR entries). */
function seedAllForms_() {
  var out = [];
  SEED_FNS_.forEach(function (fn) {
    try { out.push(fn()); } catch (e) { out.push('ERR ' + (e && e.message || e)); }
  });
  Logger.log('Reseeded: ' + out.join(', '));
  return out;
}

// Pure seed definitions for Node tooling (build-preview) — no-op in GAS.
if (typeof module !== 'undefined') module.exports = { SEED_FNS_: SEED_FNS_ };


