  ROUTERS["builder"] = function () {
/**
 * apps/builder/server/Router.js — web-app entry for the form-builder EDITOR only. One
 * project, one purpose, one doGet, no query-param mode-switching (matches talon-hub's
 * pattern — each of its apps is single-purpose). The SSO staff/student portal that used
 * to share this project now lives at apps/runner-staff; its "Open Form Builder" link
 * points straight at THIS project's own bare URL.
 * Hand-authored (not a wrap.js copy) — this is new dispatcher code, not extraction.
 */

// Deep-link tab ids an approval/template-request email button can safely land on. Anything
// else (typo, stale link) falls back to the dashboard rather than trusting the query string.
var BOOT_VIEWS_ = { responses: 1, approvals: 1 };

function doGet(e) {
  var t = HtmlService.createTemplateFromFile('pages/Index');
  t.staffEmail = '';
  t.bootError = '';
  // S14a: location.search inside the template can't be read client-side — HtmlService renders
  // into a googleusercontent.com sandbox iframe, so the browser's real /exec query string never
  // reaches Builder.html's `location`. Read it server-side instead and hand it down as a global.
  var view = (e && e.parameter && e.parameter.view) || '';
  t.bootView = BOOT_VIEWS_[view] ? view : '';
  t.bootForm = (e && e.parameter && e.parameter.form) || '';
  // Per-context branding (BRAND_NAME/BRAND_LOGO_URL/ORG_NAME Config keys -> brandTokens_,
  // Theme.js). All unset -> HCS defaults, so this changes nothing for HCS's own apps.
  var brand_ = brandTokens_();
  t.siteName = brand_.siteName;
  t.brandLogo = brand_.logoUrl;
  t.orgName = brand_.orgName;

  try {
    t.staffEmail = requireStaff_();
  } catch (err) {
    return renderDenied_(err.message);
  }

  return t.evaluate()
    .setTitle('HCS Forms — Builder')
    .addMetaTag('viewport', 'width=device-width, initial-scale=1')
    .setXFrameOptionsMode(HtmlService.XFrameOptionsMode.ALLOWALL);
}

/** Include raw file content (Theme/Builder/SharedLogic) into the Index template. */
function include_(filename) {
  if (filename === 'pages/Theme') {
    var tmpl = HtmlService.createTemplateFromFile(filename);
    tmpl.themeCss = ThemeLogic.renderThemeCss_(getThemeTokens_());
    return tmpl.evaluate().getContent();
  }
  return HtmlService.createHtmlOutputFromFile(filename).getContent();
}

function logError_(context, err) {
  var msg = (err && (err.stack || err.message)) || String(err);
  try { Logger.log('[ERR] ' + context + ': ' + msg); } catch (e) {}
  try { Mailer.sendOps('HCS Forms (builder) error — ' + context, String(msg)); } catch (e) {}
}

function renderDenied_(reason) {
  // Onward sentence, not a bare "no" — mirrors apps/runner-staff's renderDenied_ (polish item,
  // round-2 audit): a student or wrong-account arrival here is a shared/bookmarked link, not a
  // mistake on their part, so say where to go instead of just refusing.
  var portalUrl = (function () { try { return cfGetConfig_('RUNNER_STAFF_URL', ''); } catch (e) { return ''; } })();
  var msg = reason === 'ACCESS_DENIED_STUDENT'
    ? 'This tool is for staff only. If a teacher asked you to fill something out, use the link they gave you — or check Google Classroom.'
    : 'Please sign in with your Harford Christian School staff account.' +
      (portalUrl ? ' Looking for a form to fill out instead? Visit the <a href="' + Mailer.escHtml(portalUrl) + '">Forms Portal</a>.' : '');
  var html = '<!DOCTYPE html><html><head><meta charset="utf-8">' + include_('pages/Theme') + '</head><body>' +
    '<div class="page"><div class="brandbar"><span class="name">HCS Forms</span></div><div class="goldrule"></div>' +
    '<div class="card flush-top card-pad"><h1 class="form-title">Access denied</h1>' +
    '<p class="form-desc">' + msg + '</p></div></div></body></html>';
  return HtmlService.createHtmlOutput(html).setTitle('HCS Forms — Access denied');
}

/** Health check for local/manual verification of the _System wiring. */
function selfTest_() {
  var out = {};
  try { out.systemSheet = getSystemSpreadsheet_().getId(); } catch (e) { out.systemSheet = 'ERR: ' + e.message; }
  try { out.rootFolder = getRootFolder_().getId(); } catch (e) { out.rootFolder = 'ERR: ' + e.message; }
  try { out.appHandoffSecret = !!PropertiesService.getScriptProperties().getProperty('APP_HANDOFF_SECRET'); } catch (e) { out.appHandoffSecret = 'ERR: ' + e.message; }
  Logger.log(JSON.stringify(out, null, 2));
  return out;
}
  return { doGet: doGet, include_: include_ };
  };

