  t.mode = mode;
  t.formId = params.form || '';
  t.preview = params.preview ? '1' : '';
  t.editSub = params.edit || '';
  t.editToken = params.t || '';

  var reserved = { form: 1, preview: 1, edit: 1, t: 1, ssoToken: 1, guest: 1 };
  var pf = {};
  Object.keys(params).forEach(function (k) { if (!reserved[k]) pf[k] = params[k]; });
  t.prefillParams = JSON.stringify(pf).replace(/</g, '\\u003c');
  t.bootError = '';
  // Per-context branding (BRAND_NAME/BRAND_LOGO_URL/ORG_NAME Config keys -> brandTokens_,
